contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        uint256 cBalanceBefore = address(c).balance;

        // deposit via fallback
        (bool depositSuccess, ) = address(c).call{value: depositAmount}("");
        require(depositSuccess, "deposit failed");

        uint256 cBalanceAfter = address(c).balance;
        uint256 userBalanceBefore = c.balances(address(this));

        // withdraw exactly the credited balance
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 userBalanceAfter = c.balances(address(this));
        uint256 cBalanceFinal = address(c).balance;

        assert(
            cBalanceAfter == cBalanceBefore + depositAmount &&
            userBalanceBefore == depositAmount &&
            (reverted ?
                (userBalanceAfter == userBalanceBefore && cBalanceFinal == cBalanceAfter) :
                (userBalanceAfter == 0 && userBalanceBefore <= cBalanceAfter && cBalanceAfter - cBalanceFinal == userBalanceBefore)
            )
        );
    }
}

