contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(uint deposit, uint withdrawAmount) public payable {
        require(address(this).balance >= deposit, "not enough balance");
        require(withdrawAmount <= deposit, "withdrawAmount too large");

        uint beforeBal = c.balances(address(this));
        uint beforeContractBal = address(c).balance;

        (bool depositOk, ) = address(c).call{value: deposit}("");
        require(depositOk, "deposit failed");

        uint afterDepositBal = c.balances(address(this));
        require(afterDepositBal == beforeBal + deposit, "balance not credited correctly");
        require(address(c).balance == beforeContractBal + deposit, "contract balance not increased");

        bool withdrawReverted;
        try c.withdraw() { withdrawReverted = false; } catch { withdrawReverted = true; }

        assert(!withdrawReverted);
        assert(c.balances(address(this)) == 0);
        assert(address(c).balance == beforeContractBal);
    }
}

