contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address payable recipient, uint amount) public payable {
        require(recipient != address(c), "recipient cannot be the contract itself");
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "test contract needs enough balance");

        c.f{value: amount}();

        uint balanceBefore = c.balances(address(this));
        uint contractBalanceBefore = address(c).balance;

        require(balanceBefore == amount, "fallback must credit the sender");

        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(c.balances(address(this)) == balanceBefore);
            assert(address(c).balance == contractBalanceBefore);
        } else {
            assert(c.balances(address(this)) == 0);
            assert(address(this).balance == amount);
            assert(address(c).balance == contractBalanceBefore - amount);
        }
    }
}

