contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint amount) public payable {
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "test contract needs enough balance");

        (bool depositOk, ) = address(c).call{value: amount}("");
        require(depositOk, "fallback deposit must succeed");

        require(c.balances(address(this)) == amount, "fallback must credit the sender by the sent amount");

        uint256 callerBalanceBeforeWithdraw = c.balances(address(this));
        uint256 contractBalanceBeforeWithdraw = address(c).balance;

        bool firstReverted;
        try c.withdraw() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        require(!firstReverted, "first withdraw must succeed");
        require(c.balances(address(this)) == 0, "withdraw must zero the balance");
        require(address(c).balance == contractBalanceBeforeWithdraw - callerBalanceBeforeWithdraw, "withdraw must reduce contract balance by the credited amount");

        uint256 cBalanceBeforeSecond = address(c).balance;

        bool secondReverted;
        try c.withdraw() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        assert(secondReverted || c.balances(address(this)) == 0);
        assert(c.balances(address(this)) == 0);
        assert(cBalanceBeforeSecond == address(c).balance);
    }
}

