        // 3. The total recorded balances cannot exceed c's actual Ether balance.
        assert(afterBal == 0
            && cBalBefore >= beforeBal
            && cBalBefore - cBalAfter == beforeBal
            && cBalAfter <= address(c).balance);
    }

    receive() external payable {}
}

